function minEdits(a: string, b: string): number {
  const go = (i: number, j: number): number => {
    if (i === a.length) return b.length - j; // insert the rest of b
    if (j === b.length) return a.length - i; // delete the rest of a
    if (a[i] === b[j]) return go(i + 1, j + 1);
    return 1 + Math.min(go(i + 1, j + 1), go(i + 1, j), go(i, j + 1)); // replace, delete, insert
  };
  return go(0, 0);
}

