function minEdits(a: string, b: string): number {
  const m = b.length;
  const row = Array.from({ length: m + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let diag = row[0];
    row[0] = i;
    for (let j = 1; j <= m; j++) {
      const up = row[j];
      row[j] = a[i - 1] === b[j - 1] ? diag : 1 + Math.min(diag, up, row[j - 1]);
      diag = up; // old row[j] is the next column's diagonal
    }
  }
  return row[m];
}

